import os, json, glob, hashlib, math

ROOT = "storage/shared/atlas/analysis/inquirer_veritas_power_law_sim"
SWEEP_DIR = os.path.join(ROOT, "sweep_results/v4.6.6")
GLOBS = [
    os.path.join(SWEEP_DIR, "summary_v4p6p6_cfg_*.json"),
    os.path.join(SWEEP_DIR, "v4p6p6_cfg_*", "power_law_sim_summary_*_avg.json"),
]
OUT_SEL = os.path.join(SWEEP_DIR, "SELECTION_v4.6.6_v3.json")
gates = {"ptv_low":0.22, "ptv_high":0.29, "max_cv":0.35, "min_stab":0.75, "target":0.255}

def sha256(path, chunk=1<<20):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            b = f.read(chunk)
            if not b: break
            h.update(b)
    return h.hexdigest()

def extract_metrics(js):
    # Support either {'metrics': {...}} or {'avg_cycle_metrics': {...}}
    if "metrics" in js and isinstance(js["metrics"], dict):
        m = js["metrics"]
        return float(m["percent_time_in_void"]), float(m["cycle_len_cv"]), float(m["stability_score"])
    avg = js.get("avg_cycle_metrics", {}) or {}
    return float(avg["percent_time_in_void"]), float(avg["cycle_len_cv"]), float(avg["stability_score"])

files = []
for patt in GLOBS:
    for f in glob.glob(patt):
        if f not in files:
            files.append(f)
files.sort()

rows = []
for f in files:
    try:
        js = json.load(open(f, "r", encoding="utf-8"))
        ptv, cv, stab = extract_metrics(js)
        rows.append({"id": os.path.splitext(os.path.basename(f))[0], "path": f, "ptv": ptv, "cv": cv, "stab": stab})
    except Exception:
        continue

band_lo, band_hi, target = gates["ptv_low"], gates["ptv_high"], gates["target"]
band_ok = [r for r in rows if (band_lo <= r["ptv"] <= band_hi) and (r["cv"] <= gates["max_cv"]) and (r["stab"] >= gates["min_stab"])]

best = None
if band_ok:
    band_ok.sort(key=lambda r: (r["cv"], -r["stab"], abs(r["ptv"] - target)))
    best = band_ok[0]

out = {"ok": True, "counts": {"total": len(rows), "band_ok": len(band_ok)}, "gates": gates, "best_in_band": best}
os.makedirs(os.path.dirname(OUT_SEL), exist_ok=True)
json.dump(out, open(OUT_SEL, "w", encoding="utf-8"), indent=2, ensure_ascii=False)

result = {"selection_path": OUT_SEL, "selection": out, "strict": None, "tolerance": None, "readme": None}
if not best:
    print(json.dumps(result, indent=2, ensure_ascii=False)); raise SystemExit(0)

# Package strict + tolerance + README
version = "v4.6.6"
SUM = best["path"]
STRICT = os.path.join(ROOT, f"verify_config_{version}.strict.json")
TOL = os.path.join(ROOT, f"verify_config_{version}.tolerance.json")
README = os.path.join(ROOT, f"README_VERIFICATION_{version}_ACCEPTED.md")

outs = [{"path": SUM, "sha256": sha256(SUM)}]
strict_cfg = {"env": {"python": "3.10", "deps": []}, "data": [], "outputs": outs}
json.dump(strict_cfg, open(STRICT, "w", encoding="utf-8"), indent=2, ensure_ascii=False)

js = json.load(open(SUM, "r", encoding="utf-8"))
runs, rtol = 3, 0.2
avg = (js.get("avg_cycle_metrics", {}) or (js.get("metrics", {}) if "metrics" in js else {}))
std = js.get("std_cycle_metrics", {}) or {}
def tol_entry(val, std_val):
    if isinstance(std_val, (int, float)) and runs>0:
        se = float(std_val)/math.sqrt(runs); atol = 2.0*se
    else:
        atol = 0.0
    return {"mode": "tolerance", "target": float(val), "atol": float(atol), "rtol": rtol}
keys = ["num_void_cycles_detected","cycle_len_mean","cycle_len_cv","stability_score","percent_time_in_void","depth_mean","depth_min"]
metrics = {}
for key in keys:
    if key in avg:
        metrics[key] = tol_entry(avg[key], std.get(key, None))
if "avg_final_meta_edge_score" in js:
    v, s = float(js["avg_final_meta_edge_score"]), js.get("std_final_meta_edge_score", None)
    if isinstance(s, (int,float)) and runs>0: se = float(s)/math.sqrt(runs); atol = 2.0*se
    else: atol = 0.0
    metrics["avg_final_meta_edge_score"] = {"mode":"tolerance","target": v, "atol": float(atol), "rtol": rtol}
tol_cfg = {"env":{"python":"3.10","deps":[]}, "data": [], "outputs":[{"path": SUM, "metrics": metrics}]}
json.dump(tol_cfg, open(TOL, "w", encoding="utf-8"), indent=2, ensure_ascii=False)

lines = []
lines.append(f"# {version} Verification — ACCEPTED (Band-Adherent)")
lines.append(""); lines.append("Artifacts"); lines.append(f"- JSON: {SUM}"); lines.append("")
lines.append("Strict config"); lines.append(f"- {STRICT}")
lines.append("One-line strict verify")
lines.append(f"python storage/shared/agency_lab/repro_template/v2/verify.py --mode strict --config {STRICT}")
lines.append(""); lines.append("Tolerance config"); lines.append(f"- {TOL}")
lines.append("One-line tolerance verify")
lines.append(f"python storage/shared/agency_lab/repro_template/v2/verify.py --mode with-tolerance --config {TOL}")
lines.append(""); lines.append("SHA256")
for o in outs: lines.append(f"- {os.path.basename(o['path'])} → {o['sha256']}")
open(README, "w", encoding="utf-8").write("\n".join(lines))

result.update({"strict": STRICT, "tolerance": TOL, "readme": README, "headline_metrics": {k: avg.get(k) for k in ["percent_time_in_void","cycle_len_cv","stability_score"]}})
print(json.dumps(result, indent=2, ensure_ascii=False))

